[checks/demo.py]
OPERATION run_workflow success DAG with value and ref
INPUT {
  "name": "demo-success",
  "tasks": [
    {
      "id": "source",
      "task_type": "value",
      "args": {
        "value": {
          "answer": 42
        }
      }
    },
    {
      "id": "copy",
      "task_type": "value",
      "depends_on": [
        "source"
      ],
      "args": {
        "ref": "source"
      }
    }
  ]
}
